1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.concurrent.atomic.AtomicLong;
4	
5	import com.fasterxml.jackson.annotation.JsonPropertyOrder;
6	import tools.jackson.databind.ObjectMapper;
7	
8	import org.springframework.samples.petclinic.model.Owner;
9	
10	/**
11	 * Immutable structured audit event emitted when an owner is created, serialized as the JSON object
12	 * {@code {seq, ownerId, memberId, membershipLevel, event:'OWNER_CREATED'}}.
13	 *
14	 * <p>The {@code memberId} is the owner's <em>primary identifier</em> — the single value that uniquely
15	 * names the owner to the outside world, unifying the former customer code and membership number.
16	 *
17	 * <p>{@link #seq} is a process-wide, monotonically increasing sequence assigned at construction via
18	 * {@link #of(Owner)}, ordering events across every create regardless of pipeline or thread. The record
19	 * is immutable: once built, its fields never change.
20	 */
21	@JsonPropertyOrder({ "seq", "ownerId", "memberId", "membershipLevel", "event" })
22	public record OwnerCreatedEvent(long seq, Integer ownerId, String memberId,
23	        Integer membershipLevel, String event) {
24	
25	    /** The fixed event marker. */
26	    public static final String EVENT = "OWNER_CREATED";
27	
28	    /** Monotonic sequence source, shared across all creates in the process. */
29	    private static final AtomicLong SEQUENCE = new AtomicLong();
30	
31	    /** Thread-safe serializer, shared across creates. */
32	    private static final ObjectMapper MAPPER = new ObjectMapper();
33	
34	    /**
35	     * Builds the event for a persisted {@code owner}, assigning the next monotonic {@link #seq} and
36	     * stamping the {@link #EVENT} marker. The identifier is taken from the owner's
37	     * {@link Owner#getMemberId() memberId} — the owner's primary identifier.
38	     */
39	    public static OwnerCreatedEvent of(Owner owner) {
40	        return new OwnerCreatedEvent(SEQUENCE.incrementAndGet(), owner.getId(),
41	                owner.getMemberId(), owner.getMembershipLevel(), EVENT);
42	    }
43	
44	    /** Renders the event as a compact JSON object via the shared {@link ObjectMapper}. */
45	    public String toJson() {
46	        return MAPPER.writeValueAsString(this);
47	    }
48	}
