293	     */
294	    public Boolean getDeleted() {
295	        return this.deleted;
296	    }
297	
298	    public void setDeleted(Boolean deleted) {
299	        this.deleted = deleted;
300	    }
301	
302	    /** Whether this owner is soft-deleted, treating a {@code null} flag as not deleted. */
303	    public boolean isDeleted() {
304	        return Boolean.TRUE.equals(this.deleted);
305	    }
306	
307	    /**
308	     * Whether more than 80 owners had already been created on this owner's registration day,
309	     * derived at response time and not persisted. {@code true} triggers a bulk-signup warning
310	     * in the response.
