317	        this.bulkSignupWarning = bulkSignupWarning;
318	    }
319	
320	    /**
321	     * Whether this owner's city already holds between 40 and 49 owners (inclusive), approaching the
322	     * hard capacity limit of 50. Derived at response time and not persisted; {@code true} triggers a
323	     * capacity warning in the response.
324	     */
325	    public Boolean getCapacityWarning() {
326	        return this.capacityWarning;
327	    }
328	
329	    public void setCapacityWarning(Boolean capacityWarning) {
330	        this.capacityWarning = capacityWarning;
331	    }
332	
333	    /**
334	     * The number of owners in this owner's household (owners sharing the same
335	     * {@link #householdId}), derived at response time and not persisted.
336	     */
337	    public Integer getHouseholdSize() {
338	        return this.householdSize;
339	    }
340	
341	    public void setHouseholdSize(Integer householdSize) {
342	        this.householdSize = householdSize;
343	    }
344	
345	    /**
346	     * The ceiling applied to {@link #getMembershipLevel() membershipLevel}: one above the current
347	     * maximum membershipLevel among this owner's existing household members. Derived at response
348	     * time and not persisted; {@code null} means no household member exists and no cap applies.
349	     */
350	    public Integer getMembershipLevelCap() {
351	        return this.membershipLevelCap;
352	    }
353	
354	    public void setMembershipLevelCap(Integer membershipLevelCap) {
355	        this.membershipLevelCap = membershipLevelCap;
356	    }
357	
358	    /**
359	     * Whether this owner is flagged as elevated risk, derived at response time and not persisted.
360	     * {@code true} when any of three soft signals holds: the owner is a {@link #getPossibleDuplicate()
361	     * possible duplicate}; the email domain is disposable-adjacent (see
