374	    /**
375	     * The owner's membership points, derived at response time. Starts at {@code 0}, plus 2 when an
376	     * email is present, plus 1 when {@link #namesakeCount} is 0, plus 2 when the
377	     * {@link #getHouseholdSize() household} has 3 or more members, plus 3 when tenure exceeds one
378	     * elapsed fiscal year (measured from the {@link #registrationDate}; see
379	     * {@link #getTenureFiscalYears()}).
380	     */
381	    public Integer getMembershipPoints() {
382	        int points = 0;
383	        if (this.email != null && !this.email.isEmpty()) {
384	            points += 2;
385	        }
386	        if (this.namesakeCount != null && this.namesakeCount == 0) {
387	            points += 1;
388	        }
389	        if (this.householdSize != null && this.householdSize >= 3) {
390	            points += 2;
391	        }
392	        if (getTenureFiscalYears() > 1) {
393	            points += 3;
