403	     * <p>When a {@link #getMembershipLevelCap() membershipLevelCap} is present the result is capped to
404	     * it, so a new owner's level cannot exceed one above the current maximum membershipLevel among
405	     * their household members. With no household member the cap is absent and the mapped level stands.
406	     */
407	    public Integer getMembershipLevel() {
408	        int points = getMembershipPoints();
409	        int level;
410	        if (points <= 1) {
411	            level = 1;
412	        }
413	        else if (points <= 3) {
414	            level = 2;
415	        }
416	        else if (points <= 5) {
417	            level = 3;
418	        }
419	        else {
420	            level = 4;
421	        }
