455	    /**
456	     * The owner's tenure in elapsed fiscal years, measured from the {@link #registrationDate}'s
457	     * fiscal year to the current fiscal year (fiscal years start on 1 July); zero when the
458	     * registration date is absent or falls in a later fiscal year than today.
459	     */
460	    private long getTenureFiscalYears() {
461	        if (this.registrationDate == null) {
462	            return 0;
463	        }
464	        long years = (long) fiscalYear(LocalDate.now()) - fiscalYear(this.registrationDate);
465	        return Math.max(years, 0);
