472	    /** Region -> inclusive 4-digit postcode range {low, high} used to derive {@link #getLocality()}. */
473	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
474	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
