490	    /**
491	     * The region whose fixed postcode range ({@code NSW 2000-2099}, {@code VIC 3000-3099},
492	     * {@code QLD 4000-4099}) contains {@code postcode}, or {@code null} when {@code postcode} is
493	     * absent, not a 4-digit number, or in no known range.
494	     */
495	    public static String regionOfPostcode(String postcode) {
496	        if (postcode == null || postcode.isEmpty()) {
497	            return null;
498	        }
499	        int value;
500	        try {
501	            value = Integer.parseInt(postcode);
502	        } catch (NumberFormatException ex) {
503	            return null;
504	        }
505	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
506	            int[] range = entry.getValue();
507	            if (value >= range[0] && value <= range[1]) {
508	                return entry.getKey();
509	            }
510	        }
511	        return null;
512	    }
