514	    /**
515	     * The owner's region, derived at response time from the {@code REGION} prefix of the
516	     * {@link #getMemberId() memberId} (the leading run of letters before the two-digit fiscal year).
517	     * Because the member id is assigned as {@code <REGION><FY><HASH8><CHK>} with REGION taken from the
518	     * postcode, the locality follows the same region-and-hash identity as the member id.
519	     * {@code UNKNOWN} when the owner has no member id.
520	     */
521	    public String getLocality() {
522	        if (this.memberId == null) {
523	            return "UNKNOWN";
524	        }
525	        int i = 0;
526	        while (i < this.memberId.length() && Character.isLetter(this.memberId.charAt(i))) {
527	            i++;
528	        }
529	        return i == 0 ? "UNKNOWN" : this.memberId.substring(0, i);
530	    }
