19	 * {@link DetectOwnerPossibleDuplicate}.
20	 *
21	 * <p>Runs after {@link BuildOwner} (so the built owner carries its normalized telephone, lower-cased
22	 * email and last name) and before {@link SaveOwner}; the new owner has no id yet, so it never matches
23	 * itself.
24	 */
25	public class DetectOwnerDuplicate {
26	
27	    public void service(@Val Owner owner, OwnerRepository ownerRepository)
28	            throws DuplicateOwnerIdentityException {
29	        String identityKey = owner.getIdentityKey();
30	        for (Owner existing : ownerRepository.findAll()) {
31	            if (existing.getId() != null && existing.getId().equals(owner.getId())) {
32	                continue; // an owner never duplicates itself
33	            }
34	            if (existing.isDeleted()) {
35	                continue; // soft-deleted owners are ignored
36	            }
37	            if (identityKey.equals(existing.getIdentityKey())) {
38	                throw new DuplicateOwnerIdentityException(
39	                        "An owner with the same identity already exists");
40	            }
41	        }
42	    }
43	}
