565	    /**
566	     * The owner's deterministic identity key: the full lower-case hex SHA-256 of
567	     * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}. The telephone is
568	     * stored in canonical E.164 form and the email lower-cased; an absent telephone or email
569	     * contributes an empty segment, and the last name is reduced to its {@link #soundex(String)
570	     * Soundex} code. Two owners share an identity exactly when this 64-character hex value is equal.
571	     *
572	     * <p>This is the single key duplicate detection keys off: a create is rejected 409 when a
573	     * non-deleted owner already carries the same identity key (see {@code DetectOwnerDuplicate}).
574	     * Because the telephone participates in the key, two owners with the same last name and postcode
575	     * but different telephones no longer collide here — they are flagged as a soft match instead (see
576	     * {@code DetectOwnerPossibleDuplicate}). Derived at response time and not persisted.
577	     */
578	    public String getIdentityKey() {
579	        String telephone = keyPart(this.telephone);
580	        String email = this.email == null ? "" : this.email.toLowerCase(Locale.ROOT);
581	        String input = telephone + "|" + email + "|" + soundex(this.lastName);
582	        return sha256Hex(input);
583	    }
