589	    /** Full lower-case hex SHA-256 of the UTF-8 bytes of {@code value}. */
590	    private static String sha256Hex(String value) {
591	        try {
592	            byte[] digest = MessageDigest.getInstance("SHA-256")
593	                    .digest(value.getBytes(StandardCharsets.UTF_8));
594	            StringBuilder sb = new StringBuilder(digest.length * 2);
595	            for (byte b : digest) {
596	                sb.append(String.format("%02x", b));
597	            }
598	            return sb.toString();
599	        }
600	        catch (NoSuchAlgorithmException ex) {
601	            throw new IllegalStateException("SHA-256 not available", ex);
602	        }
603	    }
604	
605	    /**
606	     * The American Soundex code for {@code name}: the retained first letter followed by up to three
607	     * digits mapping the remaining consonants (b/f/p/v→1, c/g/j/k/q/s/x/z→2, d/t→3, l→4, m/n→5, r→6),
608	     * right-padded with zeros to length four. Adjacent duplicate codes collapse; {@code h}/{@code w}
609	     * do not separate repeated codes while vowels (and {@code y}) do. Non-letters are ignored. Returns
610	     * {@code ""} when {@code name} is null or has no letters. Two last names that sound alike share a
611	     * code, which is how the identity key and soft-match group surnames phonetically.
612	     */
613	    public static String soundex(String name) {
614	        if (name == null) {
615	            return "";
616	        }
617	        String letters = name.toUpperCase(Locale.ROOT).replaceAll("[^A-Z]", "");
618	        if (letters.isEmpty()) {
619	            return "";
620	        }
621	        StringBuilder code = new StringBuilder();
622	        code.append(letters.charAt(0));
623	        char prev = soundexDigit(letters.charAt(0));
624	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
625	            char c = letters.charAt(i);
626	            if (c == 'H' || c == 'W') {
627	                continue; // ignored and does not separate repeated codes
628	            }
629	            char digit = soundexDigit(c);
630	            if (digit != '0' && digit != prev) {
631	                code.append(digit);
632	            }
633	            prev = digit; // a vowel resets prev so a later same code is emitted again
634	        }
635	        while (code.length() < 4) {
636	            code.append('0');
637	        }
638	        return code.toString();
639	    }
640	
641	    /** The Soundex digit for an upper-case letter, {@code '0'} for vowels and {@code h}/{@code w}. */
642	    private static char soundexDigit(char c) {
643	        switch (c) {
644	            case 'B': case 'F': case 'P': case 'V':
645	                return '1';
646	            case 'C': case 'G': case 'J': case 'K': case 'Q': case 'S': case 'X': case 'Z':
647	                return '2';
648	            case 'D': case 'T':
649	                return '3';
650	            case 'L':
651	                return '4';
652	            case 'M': case 'N':
653	                return '5';
654	            case 'R':
655	                return '6';
656	            default:
657	                return '0';
658	        }
659	    }
660	
661	    /**
662	     * The stored E.164 {@link #telephone} formatted for humans: the country code, a space, then the
663	     * national digits (everything after the country code) grouped in threes and space-separated —
664	     * e.g. {@code +61412345678} becomes {@code +61 412 345 678}. The country code is recognised for
665	     * '+61' (2 digits) and '+1' (1 digit); any other prefix falls back to a 2-digit country code.
666	     * {@code null} when the telephone is absent or not a valid E.164 value. Derived at response time
667	     * and not persisted; the raw {@link #getTelephone() telephone} stays in E.164 form.
668	     */
669	    public String getTelephoneDisplay() {
670	        if (this.telephone == null || !this.telephone.matches("\\+\\d{8,15}")) {
671	            return null;
672	        }
673	        String digits = this.telephone.substring(1);
674	        int countryCodeLength;
675	        if (digits.startsWith("61")) {
676	            countryCodeLength = 2;
677	        }
678	        else if (digits.startsWith("1")) {
679	            countryCodeLength = 1;
680	        }
681	        else {
682	            countryCodeLength = 2;
683	        }
684	        String countryCode = digits.substring(0, countryCodeLength);
685	        String national = digits.substring(countryCodeLength);
686	        StringBuilder display = new StringBuilder("+").append(countryCode);
687	        for (int i = 0; i < national.length(); i += 3) {
688	            display.append(' ').append(national, i, Math.min(i + 3, national.length()));
689	        }
690	        return display.toString();
691	    }
692	
693	    protected Set<Pet> getPetsInternal() {
694	        if (this.pets == null) {
695	            this.pets = new HashSet<>();
696	        }
697	        return this.pets;
698	    }
699	
700	    protected void setPetsInternal(Set<Pet> pets) {
701	        this.pets = pets;
702	    }
703	
704	    public List<Pet> getPets() {
705	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
706	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
707	        return Collections.unmodifiableList(sortedPets);
708	    }
709	
710	    public void setPets(List<Pet> pets) {
711	        this.pets = new HashSet<>(pets);
712	    }
713	
714	    public void addPet(Pet pet) {
715	        getPetsInternal().add(pet);
716	        pet.setOwner(this);
717	    }
718	
719	    /**
720	     * Return the Pet with the given name, or null if none found for this Owner.
721	     *
722	     * @param name to test
723	     * @return true if pet name is already in use
724	     */
725	    public Pet getPet(String name) {
726	        return getPet(name, false);
727	    }
728	
729	    /**
730	     * Return the Pet with the given name, or null if none found for this Owner.
731	     *
732	     * @param name to test
733	     * @return true if pet name is already in use
734	     */
735	    public Pet getPet(String name, boolean ignoreNew) {
736	        name = name.toLowerCase();
737	        for (Pet pet : getPetsInternal()) {
738	            if (!ignoreNew || !pet.isNew()) {
739	                String compName = pet.getName();
740	                compName = compName.toLowerCase();
741	                if (compName.equals(name)) {
742	                    return pet;
743	                }
744	            }
745	        }
746	        return null;
747	    }
748	
749	    public Pet getPet(Integer petId) {
750	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
751	    }
752	
753	    @Override
754	    public String toString() {
755	        return new ToStringCreator(this)
756	
757	            .append("id", this.getId())
758	            .append("new", this.isNew())
759	            .append("lastName", this.getLastName())
760	            .append("firstName", this.getFirstName())
761	            .append("address", this.address)
762	            .append("city", this.city)
763	            .append("telephone", this.telephone)
764	            .append("email", this.email)
765	            .toString();
766	    }
767	}
